import java.util.*; public class Week01Problem04 {public static void main(String[] z){Scanner s=new Scanner(System.in);int r=s.nextInt(),c=s.nextInt(),mx=Integer.MIN_VALUE,mi=-1,mj=-1;long g=0;for(int i=0;i<r;i++){long t=0;for(int j=0;j<c;j++){int v=s.nextInt();t+=v;if(v>mx){mx=v;mi=i;mj=j;}}g+=t;System.out.println("Section "+(i+1)+" total: "+t);}System.out.println("Grand total: "+g);System.out.println("Balanced: "+(r>0&&g%r==0?"Yes":"No"));if(mi>=0)System.out.println("Maximum: "+mx+" at section "+(mi+1)+", index "+mj);}}